<script setup>
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {path} from '../data'
import {login,openModal} from '../session'
import {t} from '../i18n'
import Icon from '../components/Icon.vue'
const route=useRoute(),router=useRouter(),tab=ref('電子郵件'),identifier=ref(''),password=ref(''),show=ref(false),error=ref(''),success=ref('')
const identifierPrompt=computed(()=>t(tab.value==='電子郵件'?'auth.enterEmail':tab.value==='手機號碼'?'auth.enterPhone':'auth.enterUsername'))
const mode=computed(()=>route.params.auth),title=computed(()=>mode.value==='register'?'建立帳戶':mode.value==='forgot-password'?'重設密碼':'登入')
function submit(){error.value='';success.value='';if(!identifier.value.trim()){error.value=identifierPrompt.value;return}if(tab.value==='電子郵件'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(identifier.value)){error.value='請輸入有效的電子郵件地址';return}if(mode.value==='forgot-password'){success.value='演示重設流程已完成，不會寄送電子郵件。';return}if(password.value.length<6){error.value='演示密碼至少需要 6 個字元';return}password.value='';login();router.push(path('/assets'))}
</script>
<template><div class="auth-layout"><section><h1>{{ $tr("加密貨幣、外匯與全球市場 —— 集於一個平台。") }}</h1><p class="page-desc">{{ $tr("探索多元資產、智能交易工具與更靈活的交易體驗。") }}</p><div class="auth-features"><article v-for="[icon,name,desc] in [['layers','多資產交易','在同一個平台交易加密貨幣、外匯與股票。'],['sparkles','AI 量化助手','探索策略、訊號與智能投資工具。'],['shield','帳戶安全','多重安全措施，保護帳戶與資產。'],['zap','快速執行','隨時掌握市場，把握每個交易機會。']]" :key="name"><Icon :name="icon" green/><h3>{{ $tr(name) }}</h3><p>{{ $tr(desc) }}</p></article></div><RouterLink class="green-link" :to="path('/regulatory-information')">{{ $tr("監管資訊 →") }}</RouterLink></section><section class="auth-form"><div class="summary-line"><h2>{{ $tr(title) }}</h2><RouterLink class="green-link" :to="path(mode==='register'?'/login':'/register')">{{ $tr(mode==='register'?'登入':'註冊') }} →</RouterLink></div><div class="auth-tabs"><button v-for="t in ['電子郵件','手機號碼','使用者名稱']" :key="t" :class="{active:tab===t}" @click="tab=t;error=''">{{ $tr(t) }}</button></div><form class="form-stack" @submit.prevent="submit"><label>{{ $tr(tab) }}<input v-model="identifier" :placeholder="identifierPrompt" :inputmode="tab==='手機號碼'?'tel':tab==='電子郵件'?'email':'text'" autocomplete="off"/></label><label v-if="mode!=='forgot-password'">{{ $tr("密碼") }}<div class="password-field"><input v-model="password" :type="show?'text':'password'" :placeholder="$tr(&quot;請輸入演示密碼&quot;)" autocomplete="off"/><button type="button" :aria-label="$tr(show?'隱藏密碼':'顯示密碼')" @click="show=!show">{{ $tr(show?'隱藏':'顯示') }}</button></div></label><RouterLink v-if="mode==='login'" class="green-link" :to="path('/forgot-password')">{{ $tr("忘記密碼？") }}</RouterLink><p class="notice">{{ $tr("本地介面演示：請使用虛構資料。資料不會送往原站，也不會儲存密碼。") }}</p><p v-if="error" role="alert" class="form-error">{{ $tr(error) }}</p><p v-if="success" role="status" class="form-success">{{ $tr(success) }}</p><button class="primary-button wide-button">{{ $tr(mode==='login'?'立即登入':title) }}</button></form><div class="divider"><span>{{ $tr("或") }}</span></div><button class="secondary-button wide-button" @click="openModal('wallet','連接錢包')"><Icon name="wallet"/>{{ $tr(" 連接錢包") }}</button></section></div></template>
